-- 1) Sources
INSERT INTO sources (id, url, title, domain, source_type, accessed_at, is_official, is_verified, created_at) VALUES (3143, 'https://tias.kemenkeu.go.id/landing/', 'The Indonesian AID Scholarship (TIAS) - official portal | Indonesian AID, Ministry of Finance', 'tias.kemenkeu.go.id', 'scholarship', now(), true, true, now()), (3144, 'https://partnership.itb.ac.id/tias-at-itb/', 'TIAS at ITB - Directorate of Partnerships | Institut Teknologi Bandung (official)', 'partnership.itb.ac.id', 'scholarship', now(), true, true, now());

-- 2) NEW 993 TIAS
INSERT INTO scholarships (id, title, provider, country, coverage_type, amount_usd_value, deadline, degree_levels, eligible_majors, min_gpa, min_ielts, financial_need_based, merit_based, description, requirements, website_url, eligible_countries, funding_type, tuition_coverage, living_allowance, travel_allowance, accommodation, application_fee, english_requirements, required_documents, application_url, opening_date, deadline_date, deadline_type, deadline_range_start, deadline_range_end, rounds, recurrence, expected_opening_period, expected_deadline_period, application_status, last_verified_at, last_updated_at, verification_status, source_reliability, source_url, notes, is_active, university_id, award_amount, award_currency, award_period, award_basis) VALUES (993, 'The Indonesian AID Scholarship (TIAS)', 'Government of Indonesia - Indonesian AID (Ministry of Finance)', 'Indonesia', 'Full Tuition + Stipend', 0, 'Annual intakes with embassy-mediated access: choose a study programme, request portal access through the Indonesian Embassy, then apply online for administrative and academic evaluation. The 2026 intake is complete (the official portal was already announcing batch-2 selection results when this record was verified on 2026-10-28); no window for the next intake was published on the fetched pages - monitor the official portal and the Indonesian Embassy.', '["Bachelor''s", "Master''s", "PhD"]', '["All Majors"]', NULL, NULL, false, true, 'Indonesia''s development-cooperation scholarship, run by Indonesian AID under the Ministry of Finance for citizens of the priority partner countries listed under Foreign Affairs Ministerial Decree 15/2020 - and Uzbekistan is explicitly on the eligible-countries list on the official portal (fetched for this record). The catch is who it is for: civil servants and officials officially nominated by their home government, not self-nominated applicants. You do not simply register online: you choose a study programme, then request portal access through the Indonesian Embassy, and only then complete the application for administrative and academic evaluation. In exchange the package is comprehensive and fully funded - tuition and matriculation, round-trip airfare, visa costs, health insurance, monthly living and accommodation allowances, a settle-in allowance, research and education support funds, international seminar and journal-publication costs, a buddy programme and language courses (the fetched official pages list the components but publish no monetary amounts, so none are encoded here). Study is preceded by up to six months of Indonesian-language training (BIPA - compulsory for all awardees, with a Level 1 certificate on completion) and up to four months of matriculation, then a diploma (up to 36 months), bachelor or applied bachelor (48 months), master or applied master (24 months) or doctorate (48 months) at Indonesian universities and polytechnics; Institut Teknologi Bandung''s official host page, for example, lists dozens of TIAS study programmes across bachelor, master and doctoral levels. Holders must return home and serve for at least two years after graduating. The 2026 intake has already run its course (batch-2 selection results were being announced on the portal at verification), so treat this as an annual channel to prepare for through your government employer and the Indonesian Embassy well ahead of the next intake. For a self-applied Indonesian government route, compare the KNB Scholarship (record 579), under which ITB is also a host.', 'From the official portal (all levels unless stated): citizenship of a priority country - Uzbekistan is listed; official nomination by your government; not an active military member and not undergoing military service during the academic period; passport valid at least 18 months from registration; a good-conduct/clear-criminal-record letter from the local authorities; physical and mental health evidenced by a medical certificate, with a health test after selection; and willingness to return and serve at home for at least 2 years. At least 2 years of government-sector work experience is preferred; if currently employed, add your supervisor''s permission letter and a certificate of government employment. Age caps on 31 July of the application year: 25 (diploma D3), 30 (D4/bachelor), 42 (master), 47 (doctorate). English: TOEFL ITP at least 477 or IELTS at least 5.5 for diploma/bachelor/master entry, and TOEFL ITP at least 530 or IELTS at least 6.0 for doctoral entry - certificates from the last 2 years, prediction tests such as Duolingo accepted, waived for English-medium countries or Indonesian-taught programmes (two level-specific figures, so they stay in text rather than min_ielts). Master entry requires a legalized bachelor diploma and transcripts; doctoral entry additionally requires a recommendation letter from a prospective supervisor at a TIAS university, a statement of purpose and dissertation proposal, legalized master documents, no previous doctoral degree, and all research conducted in Indonesia. Portal access itself is requested through the Indonesian Embassy.', 'https://tias.kemenkeu.go.id/landing/', '["Uzbekistan and the other priority countries under Foreign Affairs Ministerial Decree 15/2020 (full list on the official portal) - restricted to civil servants / officials officially nominated by their government"]', 'Fully funded government grant: tuition and matriculation, round-trip airfare, visa costs, health insurance, monthly living and accommodation allowances, settle-in allowance, research and education support funds, international seminar and journal-publication costs, buddy programme, Indonesian (BIPA) and English courses - components as listed on the official portal; monetary amounts are not published there', 'Full academic costs (tuition fee, matriculation cost, selection cost) for the standard duration - doctorate up to 48 months, master 24 months, bachelor/diploma-IV 48 months, diploma 36 months - preceded by up to 6 months of BIPA Indonesian-language training and 4 months of matriculation', NULL, NULL, NULL, NULL, 'TOEFL ITP 477 or IELTS 5.5 (diploma/bachelor/master) or TOEFL ITP 530 or IELTS 6.0 (doctorate), certificates from the last 2 years; prediction tests (e.g. Duolingo) accepted; waived for English-medium countries or Indonesian-taught programmes. A compulsory Indonesian-language (BIPA) course is part of the programme.', '["Official nomination by the government of the priority state (portal access is requested via the Indonesian Embassy)", "Passport valid at least 18 months from registration", "Legalized diploma(s) and academic transcripts (bachelor for master entry; master for doctoral entry)", "English certificate: TOEFL ITP 477+/IELTS 5.5+ (530+/6.0+ for doctorate), within the last 2 years, unless waived", "Certificate of government-sector employment and, if employed, supervisor permission letter", "Good-conduct / clear criminal record letter from the local authorities", "Medical certificate (health test after selection)", "Doctoral only: prospective-supervisor recommendation letter and statement of purpose with dissertation proposal"]', 'https://tias.kemenkeu.go.id/landing/', NULL, NULL, 'not_published', NULL, NULL, '[{"name": "2026 intake (selection completed)", "status": "Batch-2 selection results announced on the official portal by late October 2026; accepted applicants confirm through their portal account and contact the host university international office.", "deadline_date": null}, {"name": "Annual pattern", "status": "Embassy-mediated access first (request login via the Indonesian Embassy), then online application and administrative + academic evaluation; prepare the government nomination early. Age caps are reckoned on 31 July of the application year.", "deadline_date": null}]', 'annual', NULL, NULL, 'upcoming', now(), now(), 'verified', 10, 'https://tias.kemenkeu.go.id/landing/', 'Enrichment Batch 31 (2026-10-28) candidate add - TIAS taken up after Pass 124 surfaced it on ITB''s official inbound-scholarships index (source 3142) without cataloguing it. Evidence fetched first-hand today: the official TIAS portal landing page chunks 0-2 of 4 (new source 3143: grant programme of Indonesian AID/Ministry of Finance for grantee priority areas under Foreign Affairs Ministerial Decree 15/2020 - the eligible-countries flag list and text list both name Uzbekistan; targeted at civil servants or recommended officials; levels diploma/applied bachelor/bachelor/master/applied master/doctoral; compulsory BIPA course with Level 1 certificate and matriculation; durations 36/48/24/48 months; the 16-item coverage list with NO monetary amounts; full per-level requirements incl. government nomination, citizenship, non-military conditions, 2-year return-and-serve, age caps 25/30/42/47 on 31 July, English TOEFL ITP 477/IELTS 5.5 and doctoral 530/6.0 with 2-year validity and prediction-test acceptance, legalized documents, doctoral supervisor-recommendation + SoP/dissertation proposal + no prior doctorate + research in Indonesia; how-to-apply = embassy-requested portal access then administrative and academic evaluation; 2026 batch-2 results announcement) and ITB''s official TIAS host page (new source 3144: full ITB programme tables by level, mirrored coverage list and per-level requirements). Chunk 3 of the landing (results-banner remainder) and the intake-2026 booklet PDF were not read; the portal''s university/programme tables render empty without JavaScript, so host examples rely on the ITB page. Encoding: multi-component fully funded package with no published amounts -> award NULL IDR month variable; two level-specific English bars kept textual, min_ielts/min_gpa NULL; status upcoming/not_published (2026 selection complete, next window unpublished); university_id NULL (multi-university national scheme); no university_scholarships row. Cross-references: KNB = 579 (self-applied national scheme), Ganesha Talent = 541 (ITB-funded). Rel 10.', true, NULL, NULL, 'IDR', 'month', 'variable');

-- 3) 541 micro-repair (minima never belonged to the fellowship; rel stays 7)
UPDATE scholarships SET min_gpa = NULL, min_ielts = NULL, accommodation = NULL, notes = notes || ' BATCH 31 MICRO-REPAIR 2026-10-28: min_gpa 3.0 and min_ielts 5.5 removed - they never belonged to the Ganesha Talent-International Fellowship: this row''s own english_requirements from the 2026-10-25 first-hand read states the fellowship sets no separate English score, and the GPA 3.00 figure in the text belongs to the separately described (region-restricted) ITB International Undergraduate Scholarship. Empty-string accommodation cleared; catalogue row us 228 availability normalised (Yes -> available). No uplift and reliability unchanged at 7: the fellowship''s own call channel could not be re-read today - ITB''s partnership page (re-fetched in Pass 124) still lists GT-IF with the deadline to be announced, but its official-site link now leads to a login system and the former sps.itb.ac.id/gta address resolves to a 404 after the graduate-school restructure into SPITM, so current call terms remain unverified. Revisit for a full uplift when a readable GT-IF call is published.', last_updated_at = now() WHERE id = 541;

-- 4) us 228 availability normalisation
UPDATE university_scholarships SET availability_status = 'available', last_verified_at = now() WHERE id = 228;

-- 5) 505 leftover typo (Pass-110)
UPDATE scholarships SET required_documents = REPLACE(required_documents, '(programe must offer the discount)', '(programme must offer the discount)'), last_updated_at = now() WHERE id = 505 AND required_documents LIKE '%programe must%';

